// ==== notificacoes_tela.js ====
// static\js\componentes\notificacoes_globais\notificacoes_tela.js
if (window.Notificacao) {
    console.warn("Notificacao já existe - evitando duplicação");
} else {

    window.Notificacao = {
        
        _container: null,
        
        _criarContainer() {
            if (this._container) return this._container;
            
            this._container = document.createElement('div');
            this._container.className = 'notificacao-container';
            document.body.appendChild(this._container);
            
            return this._container;
        },
        
        _criarItem(mensagem, tipo) {
            const icones = {
                sucesso: '✅',
                erro: '❌',
                aviso: '⚠️'
            };
            
            const item = document.createElement('div');
            item.className = `notificacao-item ${tipo}`;
            item.innerHTML = `
                <span class="notificacao-icone">${icones[tipo]}</span>
                <span class="notificacao-mensagem">${mensagem}</span>
                <button class="notificacao-fechar" onclick="this.parentElement.remove()">✕</button>
            `;
            
            return item;
        },
        
        _mostrar(mensagem, tipo, duracao = 3000) {
            const container = this._criarContainer();
            const item = this._criarItem(mensagem, tipo);
            
            container.appendChild(item);
            
            if (duracao > 0) {
                setTimeout(() => {
                    item.classList.add('saindo');
                    setTimeout(() => item.remove(), 300);
                }, duracao);
            }
            
            return item;
        },
        
        sucesso(mensagem, duracao = 3000) {
            return window.Notificacao._mostrar(mensagem, 'sucesso', duracao);
        },
        
        erro(mensagem, duracao = 5000) {
            return window.Notificacao._mostrar(mensagem, 'erro', duracao);
        },
        
        aviso(mensagem, duracao = 4000) {
            return window.Notificacao._mostrar(mensagem, 'aviso', duracao);
        }
    };

}

// ==== btn_acessar.js ====
// static/js/modules/pasta_pre_login/btn_acessar.js
// ==========================================================

(function () {
    const form = document.getElementById('formLogin');
    if (!form) return;

    form.addEventListener('submit', async function (e) {
        e.preventDefault();

        const btn          = document.getElementById('btnAcessar');
        const txtBotao     = document.getElementById('txtBotao');
        const spinner      = document.getElementById('spinnerCarregando');
        const txtCarregando = document.getElementById('txtCarregando');

        btn.disabled = true;
        txtBotao.classList.add('d-none');
        spinner.classList.remove('d-none');
        txtCarregando.classList.remove('d-none');

        const formData = new FormData(form);

        try {
            const response = await fetch('/login', { method: 'POST', body: formData });
            const data = await response.json();

            if (data.success) {
                if (window.Notificacao) window.Notificacao.sucesso(data.message);
                setTimeout(() => { window.location.href = data.redirect; }, 1000);
            } else {
                btn.disabled = false;
                txtBotao.classList.remove('d-none');
                spinner.classList.add('d-none');
                txtCarregando.classList.add('d-none');
                if (window.Notificacao) {
                    if (data.type === 'erro') window.Notificacao.erro(data.message);
                    else window.Notificacao.aviso(data.message);
                }
            }
        } catch (error) {
            btn.disabled = false;
            txtBotao.classList.remove('d-none');
            spinner.classList.add('d-none');
            txtCarregando.classList.add('d-none');
            if (window.Notificacao) window.Notificacao.erro('Erro ao conectar com o servidor');
        }
    });
})();

// ==== btn_cadastrar.js ====
