// ==========================================================

(function () {
    const form = document.getElementById('formCadastro');
    if (!form) return;

    form.addEventListener('submit', function () {
        const btn          = document.getElementById('btnCadastrar');
        const txtBotao     = document.getElementById('txtBotao');
        const spinner      = document.getElementById('spinnerCarregando');
        const txtCarregando = document.getElementById('txtCarregando');

        btn.disabled = true;
        txtBotao.classList.add('d-none');
        spinner.classList.remove('d-none');
        txtCarregando.classList.remove('d-none');
    });
})();

// ==== telefone.js ====
// static/js/modules/pasta_pre_login/telefone.js
// ==========================================================

function formatarTelefone(input) {
    let value = input.value.replace(/\D/g, '');

    if (value.length > 10) {
        value = value.replace(/^(\d{2})(\d{5})(\d{4})/, '($1) $2-$3');
    } else if (value.length > 6) {
        value = value.replace(/^(\d{2})(\d{4})(\d{0,4})/, '($1) $2-$3');
    } else if (value.length > 2) {
        value = value.replace(/^(\d{2})(\d{0,5})/, '($1) $2');
    } else {
        value = value.replace(/^(\d{0,2})/, '($1');
    }

    input.value = value;
}

document.addEventListener('DOMContentLoaded', function () {
    const tel = document.querySelector('input[name="telefone"]');
    if (tel) {
        tel.addEventListener('input', function () { formatarTelefone(this); });
    }
});

